window.AUTH=window.AUTH||{};window.AUTH["08-1224"]={"d":"08-1224","id":"2009/08-1224","n":"United States v. Comstock","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/202241/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-comstock-brief-merits","n":98}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep560/usrep560126/usrep560126.pdf","tr":true,"items":[{"t":"case","label":"Burroughs v. United States","cite":"290 U.S. 534","y":1934,"id":"scdb/1933-059","sc":1,"op":1,"sum":"within the power of Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"De Marcos v. Overholser","cite":"122 F.2d 16","y":1941,"url":"https://www.courtlistener.com/c/F.2d/122/16/","by":{"0":"26, 27"}},{"t":"case","label":"Gonzales v. Raich","cite":"545 U.S. 1","y":2005,"id":"2004/03-1454","sc":1,"op":6,"sum":"Holding that because “Congress had a rational basis” for concluding that a statute implements Commerce Clause power, the statute falls within the scope of congressional “authority to ‘make all Laws which shall be necessary and proper’ to ‘regulate Commerce . . . among the several States’ ” (ellipsis in original).","sumSrc":"opinion","by":{"0":"45"}},{"t":"case","label":"Greenwood v. United States","cite":"350 U.S. 366","y":1956,"id":"1955/460","sc":1,"op":14,"ar":2,"sum":"The District Court's action is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Higgins v. United States","cite":"205 F.2d 650","y":1953,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/205/650/","op":1,"by":{"0":"32"}},{"t":"case","label":"Howard v. Overholser","cite":"130 F.2d 429","y":1942,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/130/429/","sum":"Holding that an inmate at Saint Elizabeths could not obtain a transfer to his State of legal residence “without regard to its willingness to receive him,” because the statute contemplated that transfer would be made only if the inmate could be “delivered into the hands of the state officials who are charged with the custody of its insane residents”.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"Jackson v. Indiana","cite":"406 U.S. 715","y":1972,"id":"1971/70-5009","sc":1,"op":2,"sum":"The Indiana procedure for pretrial commitment of incompetent criminal defendants set forth in Ind. Ann. Stat. § 9-1706a provides that a trial judge with \"reasonable ground\" to believe the defendant to be incompetent to stand trial must appoint two examining physicians and schedule a competency hearing, at which the defendant may introduce evidence. If the court, on the basis of thephysicians' report and \"other …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 36"}},{"t":"case","label":"Jinks v. Richland County","cite":"538 U.S. 456","y":2003,"id":"2002/02-258","sc":1,"op":4,"sum":"Holding that a statute is authorized by the Necessary and Proper Clause when it “provides an alternative to [otherwise] unsatisfac­ tory options” that are “obviously inefﬁcient”.","sumSrc":"opinion","by":{"0":"22"}},{"t":"case","label":"Jones v. United States","cite":"463 U.S. 354","y":1983,"id":"1982/81-5195","sc":1,"sum":"When a criminal defendant establishes by a preponderance of the evidence that he is not guilty of a crime by reason of insanity, the Constitution permits the Government, on the basis of the insanity judgment, to confine him to a mental institution until such time as he has regained his sanity or is no longer a danger to himself or society.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 36, 37"}},{"t":"case","label":"Kansas v. Crane","cite":"534 U.S. 407","y":2002,"id":"2001/00-957","sc":1,"op":1,"sum":"The Court held that Hendricks set forth no requirement of total or complete lack of control, but that the Constitution does not permit commitment of the type of dangerous sexual offender considered in Hendricks without any lack-of-control determination.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Kansas v. Hendricks","cite":"521 U.S. 346","y":1997,"id":"1996/95-1649","sc":1,"op":3,"sum":"Despite Hendricks' claim that a certification of \"mental illness\" alone was too arbitrary to sustain a civil commitment order, the Court held that the Act met substantive due process standards by requiring considerable evidence of past violent sexual behavior and a present mental inclination to repeat such offenses.","sumSrc":"Oyez","by":{"0":"7, 39"}},{"t":"case","label":"Lipari v. Sears, Roebuck & Co.","cite":"497 F. Supp. 185","y":1980,"court":"D. Neb.","url":"https://www.courtlistener.com/c/F.%20Supp./497/185/","by":{"0":"32"}},{"t":"case","label":"M‘Culloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"16, 22, 23, 43"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"op":3,"ar":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Royal v. United States","cite":"274 F.2d 846","y":1960,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/274/846/","op":1,"by":{"0":"35"}},{"t":"case","label":"Sabri v. United States","cite":"541 U.S. 600","y":2004,"id":"2003/03-44","sc":1,"op":11,"sum":"Upholding Congress’ “authority under the Necessary and Proper Clause” to enact a criminal statute in furtherance of the federal power granted by the Spending Clause.","sumSrc":"opinion","by":{"0":"22, 44"}},{"t":"case","label":"Smith v. Hope Vill., Inc.","cite":"481 F. Supp. 2d 172","y":2007,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/481/172/","sum":"Holding that the duty is not extinguished upon an inmate’s release from a facility.","sumSrc":"brief:0","by":{"0":"32"}},{"t":"case","label":"United States v. Alvarez","cite":"519 F.2d 1036","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/519/1036/","by":{"0":"29"}},{"t":"case","label":"United States v. Charters","cite":"863 F.2d 302","y":1988,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/863/302/","by":{"0":"31"}},{"t":"case","label":"United States v. Curry","cite":"410 F.2d 1372","y":1969,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/410/1372/","op":1,"by":{"0":"35"}},{"t":"case","label":"United States v. DeBellis","cite":"649 F.2d 1","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/649/1/","sum":"Holding that the ongoing and indefinite commitment of a defendant could be justified only by a finding that he posed a danger to himself or others by reason of his mental illness.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"op":10,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"0":"19, 42, 43, 44"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"op":7,"ar":3,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"0":"19, 42, 43"}},{"t":"case","label":"United States v. S.A.","cite":"129 F.3d 995","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/129/995/","op":1,"by":{"0":"32"}},{"t":"case","label":"United States v. Sahhar","cite":"56 F.3d 1026","y":1995,"url":"https://www.courtlistener.com/c/F.3d/56/1026/","by":{"0":"37"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"sum":"The Court held that the Act was constitutional because when the government's interest in protecting the community outweighs individual liberty, pre-trial detention can be \"a potential solution to a pressing societal problem.\" The Act only applied to a specific list of serious offenses, placed heavy burdens on the government to prove that the arrestee posed significant threats to others, and did not prevent the accused from enjoying a speedy trial.","sumSrc":"Oyez","by":{"0":"47, 48"}},{"t":"case","label":"United States v. Steil","cite":"916 F.2d 485","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/916/485/","by":{"0":"31"}},{"t":"case","label":"United States v. Tom","cite":"565 F.3d 497","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/497/","op":1,"by":{"0":"16"}},{"t":"case","label":"Wells v. Attorney Gen. of the United States","cite":"201 F.2d 556","y":1953,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/201/556/","op":2,"by":{"0":"34, 35"}},{"t":"case","label":"White v. Treibly","cite":"19 F.2d 712","y":1927,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/19/712/","by":{"0":"25"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"11"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"12"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"12"}},{"t":"usc","label":"24 U.S.C. § 196a","url":"https://www.law.cornell.edu/uscode/text/24/196a","subs":["(1934)"],"by":{"0":"26, 25"}},{"t":"usc","label":"18 U.S.C. § 4241","url":"https://www.law.cornell.edu/uscode/text/18/4241","subs":["(1952)","(d)"],"stext":{"head":"§4241. Determination of mental competency to stand trial to undergo postrelease proceedings 1","paras":[[0,"(a) Motion To Determine Competency of Defendant.—At any time after the commencement of a prosecution for an offense and prior to the sentencing of the defendant, or at any time after the commencement of probation or supervised release and prior to the completion of the sentence, the defendant or the attorney for the Government may file a motion for a hearing to determine the mental competency of the defendant. The court shall grant the motion, or shall order such a hearing on its own motion, if there is reasonable cause to believe that the defendant may presently be suffering from a mental disease or defect rendering him mentally incompetent to the extent that he is unable to understand the nature and consequences of the proceedings against him or to assist properly in his defense."],[0,"(b) Psychiatric or Psychological Examination and Report.—Prior to the date of the hearing, the court may order that a psychiatric or psychological examination of the defendant be conducted, and that a psychiatric or psychological report be filed with the court, pursuant to the provisions of section 4247(b) and (c)."],[0,"(c) Hearing.—The hearing shall be conducted pursuant to the provisions of section 4247(d)."],[0,"(d) Determination and Disposition.—If, after the hearing, the court finds by a preponderance of the evidence that the defendant is presently suffering from a mental disease or defect rendering him mentally incompetent to the extent that he is unable to understand the nature and consequences of the proceedings against him or to assist properly in his defense, the court shall commit the defendant to the custody of the Attorney General. The Attorney General shall hospitalize the defendant for treatment in a suitable facility—"],[1,"(1) for such a reasonable period of time, not to exceed four months, as is necessary to determine whether there is a substantial probability that in the foreseeable future he will attain the capacity to permit the proceedings to go forward; and"],[1,"(2) for an additional reasonable period of time until—"],[2,"(A) his mental condition is so improved that trial may proceed, if the court finds that there is a substantial probability that within such additional period of time he will attain the capacity to permit the proceedings to go forward; or"],[2,"(B) the pending charges against him are disposed of according to law;"],[1,"whichever is earlier."],[0,"If, at the end of the time period specified, it is determined that the defendant's mental condition has not so improved as to permit the proceedings to go forward, the defendant is subject to the provisions of sections 4246 and 4248."],[0,"(e) Discharge.—When the director of the facility in which a defendant is hospitalized pursuant to subsection (d) determines that the defendant has recovered to such an extent that he is able to understand the nature and consequences of the proceedings against him and to assist properly in his defense, he shall promptly file a certificate to that effect with the clerk of the court that ordered the commitment. The clerk shall send a copy of the certificate to the defendant's counsel and to the attorney for the Government. The court shall hold a hearing, conducted pursuant to the provisions of section 4247(d), to determine the competency of the defendant. If, after the hearing, the court finds by a preponderance of the evidence that the defendant has recovered to such an extent that he is able to understand the nature and consequences of the proceedings against him and to assist properly in his defense, the court shall order his immediate discharge from the facility in which he is hospitalized and shall set the date for trial or other proceedings. Upon discharge, the defendant is subject to the provisions of chapters 207 and 227."],[0,"(f) Admissibility of Finding of Competency.—A finding by the court that the defendant is mentally competent to stand trial shall not prejudice the defendant in raising the issue of his insanity as a defense to the offense charged, and shall not be admissible as evidence in a trial for the offense charged."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4241?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§4241. Determination of mental competency to stand trial to undergo postrelease proceedings 1","tname":"Crimes and Criminal Procedure","by":{"0":"28, 28, 35, 10, 11, 10, 11, 39"}},{"t":"usc","label":"18 U.S.C. § 4244","url":"https://www.law.cornell.edu/uscode/text/18/4244","subs":["(1952)"],"stext":{"head":"§4244. Hospitalization of a convicted person suffering from mental disease or defect","paras":[[0,"(a) Motion To Determine Present Mental Condition of Convicted Defendant.—A defendant found guilty of an offense, or the attorney for the Government, may, within ten days after the defendant is found guilty, and prior to the time the defendant is sentenced, file a motion for a hearing on the present mental condition of the defendant if the motion is supported by substantial information indicating that the defendant may presently be suffering from a mental disease or defect for the treatment of which he is in need of custody for care or treatment in a suitable facility. The court shall grant the motion, or at any time prior to the sentencing of the defendant shall order such a hearing on its own motion, if it is of the opinion that there is reasonable cause to believe that the defendant may presently be suffering from a mental disease or defect for the treatment of which he is in need of custody for care or treatment in a suitable facility."],[0,"(b) Psychiatric or Psychological Examination and Report.—Prior to the date of the hearing, the court may order that a psychiatric or psychological examination of the defendant be conducted, and that a psychiatric or psychological report be filed with the court, pursuant to the provisions of section 4247(b) and (c). In addition to the information required to be included in the psychiatric or psychological report pursuant to the provisions of section 4247(c), if the report includes an opinion by the examiners that the defendant is presently suffering from a mental disease or defect but that it is not such as to require his custody for care or treatment in a suitable facility, the report shall also include an opinion by the examiner concerning the sentencing alternatives that could best accord the defendant the kind of treatment he does need."],[0,"(c) Hearing.—The hearing shall be conducted pursuant to the provisions of section 4247(d)."],[0,"(d) Determination and Disposition.—If, after the hearing, the court finds by a preponderance of the evidence that the defendant is presently suffering from a mental disease or defect and that he should, in lieu of being sentenced to imprisonment, be committed to a suitable facility for care or treatment, the court shall commit the defendant to the custody of the Attorney General. The Attorney General shall hospitalize the defendant for care or treatment in a suitable facility. Such a commitment constitutes a provisional sentence of imprisonment to the maximum term authorized by law for the offense for which the defendant was found guilty."],[0,"(e) Discharge.—When the director of the facility in which the defendant is hospitalized pursuant to subsection (d) determines that the defendant has recovered from his mental disease or defect to such an extent that he is no longer in need of custody for care or treatment in such a facility, he shall promptly file a certificate to that effect with the clerk of the court that ordered the commitment. The clerk shall send a copy of the certificate to the defendant's counsel and to the attorney for the Government. If, at the time of the filing of the certificate, the provisional sentence imposed pursuant to subsection (d) has not expired, the court shall proceed finally to sentencing and may modify the provisional sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4244?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4244. Hospitalization of a convicted person suffering from mental disease or defect","tname":"Crimes and Criminal Procedure","by":{"0":"4, 28, 30, 4"}},{"t":"usc","label":"18 U.S.C. § 4246","url":"https://www.law.cornell.edu/uscode/text/18/4246","subs":["(1952)","(a)","(d)","(d)(1)"],"stext":{"head":"§4246. Hospitalization of a person due for release but suffering from mental disease or defect","paras":[[0,"(a) Institution of Proceeding.—If the director of a facility in which a person is hospitalized certifies that a person in the custody of the Bureau of Prisons whose sentence is about to expire, or who has been committed to the custody of the Attorney General pursuant to section 4241(d), or against whom all criminal charges have been dismissed solely for reasons related to the mental condition of the person, is presently suffering from a mental disease or defect as a result of which his release would create a substantial risk of bodily injury to another person or serious damage to property of another, and that suitable arrangements for State custody and care of the person are not available, he shall transmit the certificate to the clerk of the court for the district in which the person is confined. The clerk shall send a copy of the certificate to the person, and to the attorney for the Government, and, if the person was committed pursuant to section 4241(d), to the clerk of the court that ordered the commitment. The court shall order a hearing to determine whether the person is presently suffering from a mental disease or defect as a result of which his release would create a substantial risk of bodily injury to another person or serious damage to property of another. A certificate filed under this subsection shall stay the release of the person pending completion of procedures contained in this section."],[0,"(b) Psychiatric or Psychological Examination and Report.—Prior to the date of the hearing, the court may order that a psychiatric or psychological examination of the defendant be conducted, and that a psychiatric or psychological report be filed with the court, pursuant to the provisions of section 4247(b) and (c)."],[0,"(c) Hearing.—The hearing shall be conducted pursuant to the provisions of section 4247(d)."],[0,"(d) Determination and Disposition.—If, after the hearing, the court finds by clear and convincing evidence that the person is presently suffering from a mental disease or defect as a result of which his release would create a substantial risk of bodily injury to another person or serious damage to property of another, the court shall commit the person to the custody of the Attorney General. The Attorney General shall release the person to the appropriate official of the State in which the person is domiciled or was tried if such State will assume responsibility for his custody, care, and treatment. The Attorney General shall make all reasonable efforts to cause such a State to assume such responsibility. If, notwithstanding such efforts, neither such State will assume such responsibility, the Attorney General shall hospitalize the person for treatment in a suitable facility, until—"],[1,"(1) such a State will assume such responsibility; or"],[1,"(2) the person's mental condition is such that his release, or his conditional release under a prescribed regimen of medical, psychiatric, or psychological care or treatment would not create a substantial risk of bodily injury to another person or serious damage to property of another;"],[0,"whichever is earlier. The Attorney General shall continue periodically to exert all reasonable efforts to cause such a State to assume such responsibility for the person's custody, care, and treatment."],[0,"(e) Discharge.—When the director of the facility in which a person is hospitalized pursuant to subsection (d) determines that the person has recovered from his mental disease or defect to such an extent that his release would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, he shall promptly file a certificate to that effect with the clerk of the court that ordered the commitment. The clerk shall send a copy of the certificate to the person's counsel and to the attorney for the Government. The court shall order the discharge of the person or, on the motion of the attorney for the Government or on its own motion, shall hold a hearing, conducted pursuant to the provisions of section 4247(d), to determine whether he should be released. If, after the hearing, the court finds by a preponderance of the evidence that the person has recovered from his mental disease or defect to such an extent that—"],[1,"(1) his release would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, the court shall order that he be immediately discharged; or"],[1,"(2) his conditional release under a prescribed regimen of medical, psychiatric, or psychological care or treatment would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, the court shall—"],[2,"(A) order that he be conditionally discharged under a prescribed regimen of medical, psychiatric, or psychological care or treatment that has been prepared for him, that has been certified to the court as appropriate by the director of the facility in which he is committed, and that has been found by the court to be appropriate; and"],[2,"(B) order, as an explicit condition of release, that he comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment."],[0,"The court at any time may, after a hearing employing the same criteria, modify or eliminate the regimen of medical, psychiatric, or psychological care or treatment."],[0,"(f) Revocation of Conditional Discharge.—The director of a medical facility responsible for administering a regimen imposed on a person conditionally discharged under subsection (e) shall notify the Attorney General and the court having jurisdiction over the person of any failure of the person to comply with the regimen. Upon such notice, or upon other probable cause to believe that the person has failed to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment, the person may be arrested, and, upon arrest, shall be taken without unnecessary delay before the court having jurisdiction over him. The court shall, after a hearing, determine whether the person should be remanded to a suitable facility on the ground that, in light of his failure to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment, his continued release would create a substantial risk of bodily injury to another person or serious damage to property of another."],[0,"(g) Release to State of Certain Other Persons.—If the director of a facility in which a person is hospitalized pursuant to this chapter certifies to the Attorney General that a person, against whom all charges have been dismissed for reasons not related to the mental condition of the person, is presently suffering from a mental disease or defect as a result of which his release would create a substantial risk of bodily injury to another person or serious damage to property of another, the Attorney General shall release the person to the appropriate official of the State in which the person is domiciled or was tried for the purpose of institution of State proceedings for civil commitment. If neither such State will assume such responsibility, the Attorney General shall release the person upon receipt of notice from the State that it will not assume such responsibility, but not later than ten days after certification by the director of the facility."],[0,"(h) Definition.—As used in this chapter the term \"State\" includes the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4246?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":2,"head":"§4246. Hospitalization of a person due for release but suffering from mental disease or defect","tname":"Crimes and Criminal Procedure","by":{"0":"18, 33, 7, 35, 40, 46, 7, 35, 40, 46, 46, 40"}},{"t":"usc","label":"18 U.S.C. § 4247","url":"https://www.law.cornell.edu/uscode/text/18/4247","subs":["(1952)","(a)(2)","(a)(5)","(a)(6)","(b)","(d)","(e)(1)(B)","(e)(2)","(g)","(h)"],"stext":{"head":"§4247. General provisions for chapter","paras":[[0,"(a) Definitions.—As used in this chapter—"],[1,"(1) \"rehabilitation program\" includes—"],[2,"(A) basic educational training that will assist the individual in understanding the society to which he will return and that will assist him in understanding the magnitude of his offense and its impact on society;"],[2,"(B) vocational training that will assist the individual in contributing to, and in participating in, the society to which he will return;"],[2,"(C) drug, alcohol, and sex offender treatment programs, and other treatment programs that will assist the individual in overcoming a psychological or physical dependence or any condition that makes the individual dangerous to others; and"],[2,"(D) organized physical sports and recreation programs;"],[1,"(2) \"suitable facility\" means a facility that is suitable to provide care or treatment given the nature of the offense and the characteristics of the defendant;"],[1,"(3) \"State\" includes the District of Columbia;"],[1,"(4) \"bodily injury\" includes sexual abuse;"],[1,"(5) \"sexually dangerous person\" means a person who has engaged or attempted to engage in sexually violent conduct or child molestation and who is sexually dangerous to others; and"],[1,"(6) \"sexually dangerous to others\" with respect 1 a person, means that the person suffers from a serious mental illness, abnormality, or disorder as a result of which he would have serious difficulty in refraining from sexually violent conduct or child molestation if released."],[0,"(b) Psychiatric or Psychological Examination.—A psychiatric or psychological examination ordered pursuant to this chapter shall be conducted by a licensed or certified psychiatrist or psychologist, or, if the court finds it appropriate, by more than one such examiner. Each examiner shall be designated by the court, except that if the examination is ordered under section 4245, 4246, or 4248, upon the request of the defendant an additional examiner may be selected by the defendant. For the purposes of an examination pursuant to an order under section 4241, 4244, or 4245, the court may commit the person to be examined for a reasonable period, but not to exceed thirty days, and under section 4242, 4243, 4246, or 4248, for a reasonable period, but not to exceed forty-five days, to the custody of the Attorney General for placement in a suitable facility. Unless impracticable, the psychiatric or psychological examination shall be conducted in the suitable facility closest to the court. The director of the facility may apply for a reasonable extension, but not to exceed fifteen days under section 4241, 4244, or 4245, and not to exceed thirty days under section 4242, 4243, 4246, or 4248, upon a showing of good cause that the additional time is necessary to observe and evaluate the defendant."],[0,"(c) Psychiatric or Psychological Reports.—A psychiatric or psychological report ordered pursuant to this chapter shall be prepared by the examiner designated to conduct the psychiatric or psychological examination, shall be filed with the court with copies provided to the counsel for the person examined and to the attorney for the Government, and shall include—"],[1,"(1) the person's history and present symptoms;"],[1,"(2) a description of the psychiatric, psychological, and medical tests that were employed and their results;"],[1,"(3) the examiner's findings; and"],[1,"(4) the examiner's opinions as to diagnosis, prognosis, and—"],[2,"(A) if the examination is ordered under section 4241, whether the person is suffering from a mental disease or defect rendering him mentally incompetent to the extent that he is unable to understand the nature and consequences of the proceedings against him or to assist properly in his defense;"],[2,"(B) if the examination is ordered under section 4242, whether the person was insane at the time of the offense charged;"],[2,"(C) if the examination is ordered under section 4243 or 4246, whether the person is suffering from a mental disease or defect as a result of which his release would create a substantial risk of bodily injury to another person or serious damage to property of another;"],[2,"(D) if the examination is ordered under section 4248, whether the person is a sexually dangerous person;"],[2,"(E) if the examination is ordered under section 4244 or 4245, whether the person is suffering from a mental disease or defect as a result of which he is in need of custody for care or treatment in a suitable facility; or"],[2,"(F) if the examination is ordered as a part of a presentence investigation, any recommendation the examiner may have as to how the mental condition of the defendant should affect the sentence."],[0,"(d) Hearing.—At a hearing ordered pursuant to this chapter the person whose mental condition is the subject of the hearing shall be represented by counsel and, if he is financially unable to obtain adequate representation, counsel shall be appointed for him pursuant to section 3006A. The person shall be afforded an opportunity to testify, to present evidence, to subpoena witnesses on his behalf, and to confront and cross-examine witnesses who appear at the hearing."],[0,"(e) Periodic Report and Information Requirements.—(1) The director of the facility in which a person is committed pursuant to—"],[1,"(A) section 4241 shall prepare semiannual reports; or"],[1,"(B) section 4243, 4244, 4245, 4246, or 4248 shall prepare annual reports concerning the mental condition of the person and containing recommendations concerning the need for his continued commitment. The reports shall be submitted to the court that ordered the person's commitment to the facility and copies of the reports shall be submitted to such other persons as the court may direct. A copy of each such report concerning a person committed after the beginning of a prosecution of that person for violation of section 871, 879, or 1751 of this title shall be submitted to the Director of the United States Secret Service. Except with the prior approval of the court, the Secret Service shall not use or disclose the information in these copies for any purpose other than carrying out protective duties under section 3056(a) of this title."],[0,"(2) The director of the facility in which a person is committed pursuant to section 4241, 4243, 4244, 4245, 4246, or 4248 shall inform such person of any rehabilitation programs that are available for persons committed in that facility."],[0,"(f) Videotape Record.—Upon written request of defense counsel, the court may order a videotape record made of the defendant's testimony or interview upon which the periodic report is based pursuant to subsection (e). Such videotape record shall be submitted to the court along with the periodic report."],[0,"(g) Habeas Corpus Unimpaired.—Nothing contained in section 4243, 4246, or 4248 precludes a person who is committed under either of such sections from establishing by writ of habeas corpus the illegality of his detention."],[0,"(h) Discharge.—Regardless of whether the director of the facility in which a person is committed has filed a certificate pursuant to the provisions of subsection (e) of section 4241, 4244, 4245, 4246, or 4248, or subsection (f) of section 4243, counsel for the person or his legal guardian may, at any time during such person's commitment, file with the court that ordered the commitment a motion for a hearing to determine whether the person should be discharged from such facility, but no such motion may be filed within one hundred and eighty days of a court determination that the person should continue to be committed. A copy of the motion shall be sent to the director of the facility in which the person is committed and to the attorney for the Government."],[0,"(i) Authority and Responsibility of the Attorney General.—The Attorney General—"],[1,"(A) may contract with a State, a political subdivision, a locality, or a private agency for the confinement, hospitalization, care, or treatment of, or the provision of services to, a person committed to his custody pursuant to this chapter;"],[1,"(B) may apply for the civil commitment, pursuant to State law, of a person committed to his custody pursuant to section 4243, 4246, or 4248;"],[1,"(C) shall, before placing a person in a facility pursuant to the provisions of section 4241, 4243, 4244, 4245, 4246, or 4248, consider the suitability of the facility's rehabilitation programs in meeting the needs of the person; and"],[1,"(D) shall consult with the Secretary of the Department of Health and Human Services in the general implementation of the provisions of this chapter and in the establishment of standards for facilities used in the implementation of this chapter."],[0,"(j) Sections 4241, 4242, 4243, and 4244 do not apply to a prosecution under an Act of Congress applicable exclusively to the District of Columbia or the Uniform Code of Military Justice."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4247?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§4247. General provisions for chapter","tname":"Crimes and Criminal Procedure","by":{"0":"33, 35, 8, 8, 6, 48, 6, 48, 5, 7, 7, 8, 9, 9, 9, 9"}},{"t":"usc","label":"18 U.S.C. § 4248","url":"https://www.law.cornell.edu/uscode/text/18/4248","subs":["(1952)","(a)","(c)","(d)","(d)(1)","(e)","(g)"],"stext":{"head":"§4248. Civil commitment of a sexually dangerous person","paras":[[0,"(a) Institution of Proceedings.—In relation to a person who is in the custody of the Bureau of Prisons, or who has been committed to the custody of the Attorney General pursuant to section 4241(d), or against whom all criminal charges have been dismissed solely for reasons relating to the mental condition of the person, the Attorney General or any individual authorized by the Attorney General or the Director of the Bureau of Prisons may certify that the person is a sexually dangerous person, and transmit the certificate to the clerk of the court for the district in which the person is confined. The clerk shall send a copy of the certificate to the person, and to the attorney for the Government, and, if the person was committed pursuant to section 4241(d), to the clerk of the court that ordered the commitment. The court shall order a hearing to determine whether the person is a sexually dangerous person. A certificate filed under this subsection shall stay the release of the person pending completion of procedures contained in this section."],[0,"(b) Psychiatric or Psychological Examination and Report.—Prior to the date of the hearing, the court may order that a psychiatric or psychological examination of the defendant be conducted, and that a psychiatric or psychological report be filed with the court, pursuant to the provisions of section 4247(b) and (c)."],[0,"(c) Hearing.—The hearing shall be conducted pursuant to the provisions of section 4247(d)."],[0,"(d) Determination and Disposition.—If, after the hearing, the court finds by clear and convincing evidence that the person is a sexually dangerous person, the court shall commit the person to the custody of the Attorney General. The Attorney General shall release the person to the appropriate official of the State in which the person is domiciled or was tried if such State will assume responsibility for his custody, care, and treatment. The Attorney General shall make all reasonable efforts to cause such a State to assume such responsibility. If, notwithstanding such efforts, neither such State will assume such responsibility, the Attorney General shall place the person for treatment in a suitable facility, until—"],[1,"(1) such a State will assume such responsibility; or"],[1,"(2) the person's condition is such that he is no longer sexually dangerous to others, or will not be sexually dangerous to others if released under a prescribed regimen of medical, psychiatric, or psychological care or treatment;"],[0,"whichever is earlier."],[0,"(e) Discharge.—When the Director of the facility in which a person is placed pursuant to subsection (d) determines that the person's condition is such that he is no longer sexually dangerous to others, or will not be sexually dangerous to others if released under a prescribed regimen of medical, psychiatric, or psychological care or treatment, he shall promptly file a certificate to that effect with the clerk of the court that ordered the commitment. The clerk shall send a copy of the certificate to the person's counsel and to the attorney for the Government. The court shall order the discharge of the person or, on motion of the attorney for the Government or on its own motion, shall hold a hearing, conducted pursuant to the provisions of section 4247(d), to determine whether he should be released. If, after the hearing, the court finds by a preponderance of the evidence that the person's condition is such that—"],[1,"(1) he will not be sexually dangerous to others if released unconditionally, the court shall order that he be immediately discharged; or"],[1,"(2) he will not be sexually dangerous to others if released under a prescribed regimen of medical, psychiatric, or psychological care or treatment, the court shall—"],[2,"(A) order that he be conditionally discharged under a prescribed regimen of medical, psychiatric, or psychological care or treatment that has been prepared for him, that has been certified to the court as appropriate by the Director of the facility in which he is committed, and that has been found by the court to be appropriate; and"],[2,"(B) order, as an explicit condition of release, that he comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment."],[1,"The court at any time may, after a hearing employing the same criteria, modify or eliminate the regimen of medical, psychiatric, or psychological care or treatment."],[0,"(f) Revocation of Conditional Discharge.—The director of a facility responsible for administering a regimen imposed on a person conditionally discharged under subsection (e) shall notify the Attorney General and the court having jurisdiction over the person of any failure of the person to comply with the regimen. Upon such notice, or upon other probable cause to believe that the person has failed to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment, the person may be arrested, and, upon arrest, shall be taken without unnecessary delay before the court having jurisdiction over him. The court shall, after a hearing, determine whether the person should be remanded to a suitable facility on the ground that he is sexually dangerous to others in light of his failure to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment."],[0,"(g) Release to State of Certain Other Persons.—If the director of the facility in which a person is hospitalized or placed pursuant to this chapter certifies to the Attorney General that a person, against whom all charges have been dismissed for reasons not related to the mental condition of the person, is a sexually dangerous person, the Attorney General shall release the person to the appropriate official of the State in which the person is domiciled or was tried for the purpose of institution of State proceedings for civil commitment. If neither such State will assume such responsibility, the Attorney General shall release the person upon receipt of notice from the State that it will not assume such responsibility, but not later than 10 days after certification by the director of the facility."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4248?type=usc&year=mostrecent&link-type=html"},"op":73,"ar":3,"head":"§4248. Civil commitment of a sexually dangerous person","tname":"Crimes and Criminal Procedure","by":{"0":"33, 6, 7, 19, 39, 44, 6, 7, 19, 39, 44, 7, 7, 5, 6, 8, 19, 45, 40, 9, 6"}},{"t":"law","label":"Pub. L. No. 109-248","url":"https://www.govinfo.gov/link/plaw/109/public/248","by":{"0":"5"}},{"t":"usc","label":"42 U.S.C. § 16971","url":"https://www.law.cornell.edu/uscode/text/42/16971","subs":["(a)"],"by":{"0":"46"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(b)"],"by":{"0":"41, 40"}},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(a)(2)","(b)"],"by":{"0":"44, 44"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","stext":{"head":"§1153. Offenses committed within Indian country","paras":[[0,"(a) Any Indian who commits against the person or property of another Indian or other person any of the following offenses, namely, murder, manslaughter, kidnapping, maiming, a felony under chapter 109A, incest, a felony assault under section 113, an assault against an individual who has not attained the age of 16 years, felony child abuse or neglect, arson, burglary, robbery, and a felony under section 661 of this title within the Indian country, shall be subject to the same law and penalties as all other persons committing any of the above offenses, within the exclusive jurisdiction of the United States."],[0,"(b) Any offense referred to in subsection (a) of this section that is not defined and punished by Federal law in force within the exclusive jurisdiction of the United States shall be defined and punished in accordance with the laws of the State in which such offense was committed as are in force at the time of such offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1153?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1153. Offenses committed within Indian country","tname":"Crimes and Criminal Procedure","by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/18/2241","subs":["(c)"],"by":{"0":"48, 11"}},{"t":"usc","label":"18 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/18/2244","subs":["(a)(1)"],"by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 2251","url":"https://www.law.cornell.edu/uscode/text/18/2251","by":{"0":"48"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(d)","(e)(3)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"38, 20, 38, 38"}},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(d)(3)"],"by":{"0":"38, 41"}},{"t":"usc","label":"18 U.S.C. § 4243","url":"https://www.law.cornell.edu/uscode/text/18/4243","subs":["(e)"],"stext":{"head":"§4243. Hospitalization of a person found not guilty only by reason of insanity","paras":[[0,"(a) Determination of Present Mental Condition of Acquitted Person.—If a person is found not guilty only by reason of insanity at the time of the offense charged, he shall be committed to a suitable facility until such time as he is eligible for release pursuant to subsection (e)."],[0,"(b) Psychiatric or Psychological Examination and Report.—Prior to the date of the hearing, pursuant to subsection (c), the court shall order that a psychiatric or psychological examination of the defendant be conducted, and that a psychiatric or psychological report be filed with the court, pursuant to the provisions of section 4247(b) and (c)."],[0,"(c) Hearing.—A hearing shall be conducted pursuant to the provisions of section 4247(d) and shall take place not later than forty days following the special verdict."],[0,"(d) Burden of Proof.—In a hearing pursuant to subsection (c) of this section, a person found not guilty only by reason of insanity of an offense involving bodily injury to, or serious damage to the property of, another person, or involving a substantial risk of such injury or damage, has the burden of proving by clear and convincing evidence that his release would not create a substantial risk of bodily injury to another person or serious damage of property of another due to a present mental disease or defect. With respect to any other offense, the person has the burden of such proof by a preponderance of the evidence."],[0,"(e) Determination and Disposition.—If, after the hearing, the court fails to find by the standard specified in subsection (d) of this section that the person's release would not create a substantial risk of bodily injury to another person or serious damage of property of another due to a present mental disease or defect, the court shall commit the person to the custody of the Attorney General. The Attorney General shall release the person to the appropriate official of the State in which the person is domiciled or was tried if such State will assume responsibility for his custody, care, and treatment. The Attorney General shall make all reasonable efforts to cause such a State to assume such responsibility. If, notwithstanding such efforts, neither such State will assume such responsibility, the Attorney General shall hospitalize the person for treatment in a suitable facility until—"],[1,"(1) such a State will assume such responsibility; or"],[1,"(2) the person's mental condition is such that his release, or his conditional release under a prescribed regimen of medical, psychiatric, or psychological care or treatment, would not create a substantial risk of bodily injury to another person or serious damage to property of another;"],[0,"whichever is earlier. The Attorney General shall continue periodically to exert all reasonable efforts to cause such a State to assume such responsibility for the person's custody, care, and treatment."],[0,"(f) Discharge.—When the director of the facility in which an acquitted person is hospitalized pursuant to subsection (e) determines that the person has recovered from his mental disease or defect to such an extent that his release, or his conditional release under a prescribed regimen of medical, psychiatric, or psychological care or treatment, would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, he shall promptly file a certificate to that effect with the clerk of the court that ordered the commitment. The clerk shall send a copy of the certificate to the person's counsel and to the attorney for the Government. The court shall order the discharge of the acquitted person or, on the motion of the attorney for the Government or on its own motion, shall hold a hearing, conducted pursuant to the provisions of section 4247(d), to determine whether he should be released. If, after the hearing, the court finds by the standard specified in subsection (d) that the person has recovered from his mental disease or defect to such an extent that—"],[1,"(1) his release would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, the court shall order that he be immediately discharged; or"],[1,"(2) his conditional release under a prescribed regimen of medical, psychiatric, or psychological care or treatment would no longer create a substantial risk of bodily injury to another person or serious damage to property of another, the court shall—"],[2,"(A) order that he be conditionally discharged under a prescribed regimen of medical, psychiatric, or psychological care or treatment that has been prepared for him, that has been certified to the court as appropriate by the director of the facility in which he is committed, and that has been found by the court to be appropriate; and"],[2,"(B) order, as an explicit condition of release, that he comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment."],[0,"The court at any time may, after a hearing employing the same criteria, modify or eliminate the regimen of medical, psychiatric, or psychological care or treatment."],[0,"(g) Revocation of Conditional Discharge.—The director of a medical facility responsible for administering a regimen imposed on an acquitted person conditionally discharged under subsection (f) shall notify the Attorney General and the court having jurisdiction over the person of any failure of the person to comply with the regimen. Upon such notice, or upon other probable cause to believe that the person has failed to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment, the person may be arrested, and, upon arrest, shall be taken without unnecessary delay before the court having jurisdiction over him. The court shall, after a hearing, determine whether the person should be remanded to a suitable facility on the ground that, in light of his failure to comply with the prescribed regimen of medical, psychiatric, or psychological care or treatment, his continued release would create a substantial risk of bodily injury to another person or serious damage to property of another."],[0,"(h) Limitations on Furloughs.—An individual who is hospitalized under subsection (e) of this section after being found not guilty only by reason of insanity of an offense for which subsection (d) of this section creates a burden of proof of clear and convincing evidence, may leave temporarily the premises of the facility in which that individual is hospitalized only—"],[1,"(1) with the approval of the committing court, upon notice to the attorney for the Government and such individual, and after opportunity for a hearing;"],[1,"(2) in an emergency; or"],[1,"(3) when accompanied by a Federal law enforcement officer (as defined in section 115 of this title)."],[0,"(i) Certain Persons Found Not Guilty by Reason of Insanity in the District of Columbia.—"],[1,"(1) Transfer to custody of the attorney general.—Notwithstanding section 301(h) of title 24 of the District of Columbia Code, and notwithstanding subsection 4247(j) of this title, all persons who have been committed to a hospital for the mentally ill pursuant to section 301(d)(1) of title 24 of the District of Columbia Code, and for whom the United States has continuing financial responsibility, may be transferred to the custody of the Attorney General, who shall hospitalize the person for treatment in a suitable facility."],[1,"(2) Application.—"],[2,"(A) In general.—The Attorney General may establish custody over such persons by filing an application in the United States District Court for the District of Columbia, demonstrating that the person to be transferred is a person described in this subsection."],[2,"(B) Notice.—The Attorney General shall, by any means reasonably designed to do so, provide written notice of the proposed transfer of custody to such person or such person's guardian, legal representative, or other lawful agent. The person to be transferred shall be afforded an opportunity, not to exceed 15 days, to respond to the proposed transfer of custody, and may, at the court's discretion, be afforded a hearing on the proposed transfer of custody. Such hearing, if granted, shall be limited to a determination of whether the constitutional rights of such person would be violated by the proposed transfer of custody."],[2,"(C) Order.—Upon application of the Attorney General, the court shall order the person transferred to the custody of the Attorney General, unless, pursuant to a hearing under this paragraph, the court finds that the proposed transfer would violate a right of such person under the United States Constitution."],[2,"(D) Effect.—Nothing in this paragraph shall be construed to—"],[3,"(i) create in any person a liberty interest in being granted a hearing or notice on any matter;"],[3,"(ii) create in favor of any person a cause of action against the United States or any officer or employee of the United States; or"],[3,"(iii) limit in any manner or degree the ability of the Attorney General to move, transfer, or otherwise manage any person committed to the custody of the Attorney General."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/4243?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§4243. Hospitalization of a person found not guilty only by reason of insanity","tname":"Crimes and Criminal Procedure","by":{"0":"4, 4, 46"}},{"t":"usc","label":"18 U.S.C. § 4245","url":"https://www.law.cornell.edu/uscode/text/18/4245","by":{"0":"4"}},{"t":"usc","label":"24 U.S.C. § 191a","url":"https://www.law.cornell.edu/uscode/text/24/191a","subs":["(1946)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 194","url":"https://www.law.cornell.edu/uscode/text/24/194","subs":["(1925)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 195","url":"https://www.law.cornell.edu/uscode/text/24/195","subs":["(1925)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 195a","url":"https://www.law.cornell.edu/uscode/text/24/195a","subs":["(1952)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 196","url":"https://www.law.cornell.edu/uscode/text/24/196","subs":["(1925)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 196b","url":"https://www.law.cornell.edu/uscode/text/24/196b","subs":["(1940)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 222","url":"https://www.law.cornell.edu/uscode/text/24/222","subs":["(1946)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 225","url":"https://www.law.cornell.edu/uscode/text/24/225","subs":["(a)(4)(iv)","(a)(5)(i)"],"by":{"0":"25, 25"}},{"t":"usc","label":"24 U.S.C. § 225g","url":"https://www.law.cornell.edu/uscode/text/24/225g","subs":["(b)"],"by":{"0":"25"}},{"t":"usc","label":"24 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/24/321","by":{"0":"25"}}]};